// harness.c
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdio.h>

// Simplified/adapter version of the OpenSSL apps function
// Potential bug: allocates only strlen(in) bytes (missing +1),
// which can overflow by 1 when encoding the leading length byte.
unsigned char *next_protos_parse(size_t *outlen, const char *in) {
    if (outlen == NULL || in == NULL)
        return NULL;

    size_t inlen = strlen(in);
    // BUG: should be inlen + 1 to accommodate the length byte overhead
    unsigned char *out = (unsigned char *)malloc(inlen);
    if (out == NULL)
        return NULL;

    unsigned char *p = out;
    const char *start = in;
    const char *end;

    while (*start != '\0') {
        // find end of token (comma separated)
        end = start;
        while (*end != '\0' && *end != ',')
            end++;
        size_t toklen = (size_t)(end - start);
        // Minimal checks (OpenSSL checks 1..255). Here we just cast.
        unsigned char lb = (unsigned char)toklen;
        // write length byte and data
        *p++ = lb; // Potential 1-byte OOB if inlen == strlen(in) is exact
        if (toklen > 0) {
            memcpy(p, start, toklen);
            p += toklen;
        }
        if (*end == ',')
            start = end + 1;
        else
            start = end;
        if (*start == ',') // skip multiple delimiters
            start++;
    }

    *outlen = (size_t)(p - out);
    return out;
}

