// harness.c
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

// Converts in-place; assumes NUL-terminated input.
// Walking until '\0' on a non-terminated buffer causes OOB reads/writes.
void make_uppercase(char *string) {
    if (string == NULL)
        return;
    unsigned char *p = (unsigned char *)string;
    while (*p) {
        if (*p >= 'a' && *p <= 'z')
            *p = (unsigned char)(*p - ('a' - 'A'));
        p++;
    }
}

