// harness.c
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

// Overwrites the string using its length via strlen().
// If the input is not NUL-terminated, strlen reads out-of-bounds
// and the subsequent writes also go out-of-bounds.
void cleanse(char *str) {
    if (str == NULL)
        return;
    size_t n = strlen(str); // OOB read if no NUL
    volatile unsigned char *p = (volatile unsigned char *)str;
    for (size_t i = 0; i < n; i++) {
        p[i] = 0; // OOB write if n exceeds allocation
    }
}

