// harness.c
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

static void local_cleanse(char *str) {
    if (str == NULL) return;
    size_t n = strlen(str);
    volatile unsigned char *p = (volatile unsigned char *)str;
    for (size_t i = 0; i < n; i++) p[i] = 0;
}

// Frees the buffer after cleansing. Calling twice on the same pointer will
// cause a double free.
void clear_free(char *str) {
    if (str == NULL)
        return;
    local_cleanse(str);
    free(str);
}

