// harness.c
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

// Parse next item from a comma/space separated list by inserting NUL.
// Scans until NUL; if input not terminated, will read/write out-of-bounds.
char *next_item(char *opt) {
    if (opt == NULL)
        return NULL;
    char *p = opt;
    // skip leading separators
    while (*p == ',' || *p == ' ')
        p++;
    char *start = p;
    while (*p != '\0' && *p != ',' && *p != ' ')
        p++;
    if (*p != '\0') {
        *p = '\0'; // in-place terminate current item
        p++;
    }
    (void)p; // caller would typically continue with p
    return start;
}

