// harness.c
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdio.h>

// Minimal BIO stand-in
typedef struct BIO_st {
    unsigned char *data;
    size_t len;
    size_t pos;
} BIO;

static int bio_read(BIO *in, unsigned char *buf, int max) {
    if (in == NULL || buf == NULL || max <= 0) return -1;
    size_t remain = (in->pos < in->len) ? (in->len - in->pos) : 0;
    if (remain == 0) return 0;
    size_t n = (remain > (size_t)max) ? (size_t)max : remain;
    memcpy(buf, in->data + in->pos, n);
    in->pos += n;
    return (int)n;
}

// Simplified version with a deliberate growth bug: copies more than allocated.
int bio_to_mem(unsigned char **out, size_t *outlen, size_t maxlen, BIO *in) {
    if (out == NULL || outlen == NULL || in == NULL)
        return 0;

    unsigned char tmp[8];
    size_t size = 0;
    unsigned char *buf = (unsigned char *)malloc(1); // too small
    if (buf == NULL)
        return 0;

    for (;;) {
        int n = bio_read(in, tmp, (int)sizeof(tmp));
        if (n <= 0)
            break;
        // BUG: missing realloc to grow buffer; memcpy will overflow buf
        memcpy(buf + size, tmp, (size_t)n); // CWE-787
        size += (size_t)n;
        if (maxlen != 0 && size >= maxlen)
            break;
    }

    // NUL-terminate (may also overflow by one)
    if (size + 1 > 0) {
        // This write can also be OOB
        buf[size] = '\0';
    }

    *out = buf;
    *outlen = size;
    return 1;
}

