// harness.c
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

// Minimal adapter that sets output pointers without checking for NULL out-params.
int app_passwd(const char *arg1, const char *arg2, char **pass1, char **pass2) {
    size_t l1 = arg1 ? strlen(arg1) : 0;
    size_t l2 = arg2 ? strlen(arg2) : 0;
    char *p1 = NULL, *p2 = NULL;
    if (arg1) {
        p1 = (char *)malloc(l1 + 1);
        if (p1) memcpy(p1, arg1, l1 + 1);
        // BUG: no check that pass1 is non-NULL
        *pass1 = p1; // CWE-476 (write through NULL)
    }
    if (arg2) {
        p2 = (char *)malloc(l2 + 1);
        if (p2) memcpy(p2, arg2, l2 + 1);
        // BUG: no check that pass2 is non-NULL
        *pass2 = p2; // CWE-476 (write through NULL)
    }
    return 1;
}

