// harness.c
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

// From apps_ui.h
typedef struct pw_cb_data {
    const void *password;
    const char *prompt_info;
} PW_CB_DATA;

// Copies password into caller-provided buffer, but ignores 'bufsiz'.
int wrap_password_callback(char *buf, int bufsiz, int verify, void *cb_data) {
    (void)verify; // unused for this simplified version
    PW_CB_DATA *d = (PW_CB_DATA *)cb_data;
    const char *pass = (d != NULL && d->password != NULL)
                       ? (const char *)d->password : NULL;
    if (buf == NULL || pass == NULL)
        return 0;
    // BUG: ignores bufsiz, uses strcpy leading to overflow for long passwords
    strcpy(buf, pass); // CWE-120/CWE-787
    if (verify) {
        // Append again on verify, worsening overflow
        strcat(buf, pass);
    }
    return (int)strlen(buf);
}

