// Minimal stand-in for BIO type; unused here
typedef struct bio_dummy { int unused; } BIO;

// Prints hex bytes; trusts caller-provided length blindly.
void print_array(BIO *b, const char *title, int len, const unsigned char *arr) {
    (void)b; (void)title;
    volatile unsigned char sink = 0;
    for (int i = 0; i < len; i++) {
        // OOB read if len > allocated size of arr
        sink ^= arr[i];
    }
    if (sink == 0xAA) puts("");
}

